export type ScenarioType='REQUESTED'|'PROPOSED_CAP'|'DOWNSIDE'|'CUSTOM';
export type MaybeNumber=number|null;
export interface BorrowerProfile {companyName:string;businessType:'MINING_CONTRACTOR'|'CIVIL_CONSTRUCTION'|'LOGISTICS'|'PLANTATION';operatingSinceYear:number;slikStatus:'COL_1_CURRENT'|'COL_2_SPECIAL_MENTION'|'COL_3_SUBSTANDARD'|'COL_4_DOUBTFUL'|'COL_5_LOSS';slikNotes:string;rkabApprovalStatus:'APPROVED'|'PENDING'|'EXEMPT';ownershipStructure:string;}
export interface GroupObligorProfile {parentHoldingName:string;ultimateBeneficialOwner:string;totalGroupBankExposure:number;allBankGroupExposure:number;bankLegalLendingLimitBMPK:number;exposureScope:string;guaranteeStructure:'PERSONAL_GUARANTEE'|'CORPORATE_GUARANTEE'|'JOINT_SEVERAL'|'NONE';crossDefaultClauseEnforceable:boolean;}
export interface BankStatementMonth {periodMonth:string;totalCreditMutation:number;totalDebitMutation:number;intercompanyCredits:number;nonRevenueCredits:number;averageDailyBalance:number;endingBalance:number;bouncedChecksCount:number;lowBalanceDays:number;circularTransactionCount:number;}
export interface BankReconciliationModule {statements:BankStatementMonth[];declaredAnnualRevenue:number;comparisonPeriod:string;annualizePartial:boolean;}
export type SpreadNumericKey='revenue'|'cogs'|'operatingExpenses'|'depreciationAmortization'|'interestExpense'|'taxExpense'|'operatingCashFlow'|'currentAssets'|'accountsReceivable'|'cashAndEquivalents'|'currentLiabilities'|'totalGrossDebt'|'totalAssets'|'totalLiabilities'|'equity'|'cashTaxesPaid'|'increaseInNWC'|'maintenanceCapex'|'mandatoryDistributions'|'affiliateReceivableAdjustment';
export type FinancialStatementYear=Record<SpreadNumericKey,MaybeNumber>&{fiscalYear:number;periodType:'ANNUAL'|'YTD';periodMonths:number;sourceReference:string;auditTier:'BIG_4'|'TIER_2_AFFILIATED'|'LOCAL_KAP'|'IN_HOUSE_UNAUDITED';auditOpinion:'WTP_UNQUALIFIED'|'WDP_QUALIFIED'|'DISCLAIMER_ADVERSE';auditQualityHaircutPct:number;normalizationAdjustments:{description:string;amount:number;enabled:boolean}[];};
export interface ExistingDebtFacility {id:string;creditorName:string;facilityType:'WORKING_CAPITAL_KMK'|'TERM_LOAN'|'LEASING'|'LC_SKBDN';isRevolving:boolean;limitAmount:number;outstandingBalance:number;monthlyPrincipalRepayment:number;annualInterestRate:number;collateralDescription:string;collateralValueAllocated:number;availabilityConfirmed:boolean;atLendingInstitution:boolean;}
export interface EquipmentDealInputs {numberOfUnits:number;unitCost:number;requestedFinancingPct:number;proposedCapFinancingPct:number;tenorMonths:number;annualInterestRate:number;repaymentStructure:'EQUAL_PRINCIPAL'|'ANNUITY';gracePeriodMonths:number;plannedHoursPerMonthPerUnit:number;billingTariffPerHour:number;fuelConsumptionLitersPerHour:number;fuelPricePerLiter:number;fuelPassThroughPct:number;operatorCostPerUnitMonth:number;maintenanceReservePerUnitMonth:number;sgAndAAllocationPerUnitMonth:number;pph23WithholdingRate:number;cashTaxRate:number;withholdingCreditRealizedPct:number;debtServiceReserveMonths:number;unrestrictedCashAvailable:number;assetMarketValueNew:number;forcedSaleValuePct:number;annualAssetDepreciationRate:number;realizationCostPct:number;realizationFixedCost:number;liquidationDelayMonths:number;}
/** Existing valuation inputs remain canonical in equipmentDeal; the delivery discount is stored here to avoid duplicate editable values. */
export interface CollateralValuationModel {immediateDeliveryDepreciationPct:number;}
export interface CollateralMonthSnapshot {month:number;outstandingDebt:number;assetMarketValue:number;grossForcedSaleValue:number;netForcedSaleValue:number;negativeEquityGap:number;netCoverage:MaybeNumber;}
export interface CollateralDeficitAnalysis {schedule:CollateralMonthSnapshot[];hasDeficitWindow:boolean;peakDeficitAmount:number;peakDeficitMonth:number|null;unsecuredWindowStartMonth:number|null;unsecuredWindowEndMonth:number|null;deficitMonths:number;requiredExtraDownPaymentToCure:number;maximumSecuredPrincipal:number;equityAfterCure:number;}
export interface LegalDiligenceItem {id:string;category:'CORPORATE_AUTHORITY'|'COLLATERAL_PERFECTION'|'INSURANCE'|'ESCROW_CASH_CONTROL';itemDescription:string;legalBasisIndonesianLaw:string;stage:'CONDITION_PRECEDENT_CP'|'CONDITION_SUBSEQUENT_CS';isMandatoryForDisbursement:boolean;isVerified:boolean;verifiedByAnalyst:string;documentRefNumber:string;notes:string;dueDate:string;}
export interface OfftakerContractProtection {offtakerName:string;tierClassification:'TIER_1_CONCESSIONAIRE'|'TIER_2_MID_MINER'|'SUB_CONTRACTOR';remainingContractMonths:number;hasGuaranteedMinimumHours:boolean;standbyHourlyRate:number;guaranteedHoursPerUnitMonth:number;hasEarlyTerminationPenalty:boolean;contractEvidenceVerified:boolean;}
export interface ScenarioAdjustment {name:string;utilizationPct:number;tariffAdjustmentPct:number;fuelPriceShockPct:number;dsoShockDays:number;interestShockBps:number;seasonalQ1Factor:number;standbyHoursPerUnitMonth:number;}
export interface QualitativeScorecardInputs {managementExperienceScore:number;offtakerCreditworthinessScore:number;contractTenorVsLoanTenorScore:number;regulatoryComplianceScore:number;equipmentMarketabilityScore:number;evidenceNotes:string;}
export interface TriangularDistribution {min:number;mode:number;max:number;}
export interface HistogramBin {lower:number;upper:number;midPoint:number;count:number;}
export interface MonteCarloSimulationOutput {iterations:number;seed:number;scenario:ScenarioType;inputSnapshot:string;executionTimeMs:number;generatedAt:string;model:string;probabilities:{probCovenantBreachPct:MaybeNumber;probTechnicalDefaultPct:MaybeNumber;probLiquidityShortfallPct:number;probLifecycleCashShortfallPct:number};quantiles:{p5_severeDownside:MaybeNumber;p25_downside:MaybeNumber;p50_median:MaybeNumber;p75_base:MaybeNumber;p95_upside:MaybeNumber};liquidityQuantiles:{p5_liquidity:number;medianLiquidity:number;p5_lifecycleMinimum:number};lifecycleQuantiles:{p5_minimumDSCR:MaybeNumber;p50_minimumDSCR:MaybeNumber};histogram:HistogramBin[];tariffFloorCount:number;}
export interface MonteCarloWorkspaceConfig {iterations:number;seed:number;scenario:ScenarioType;distributions:{utilization:TriangularDistribution;dsoDays:TriangularDistribution;fuelVolatility:number;tariffVolatility:number};latestResults:MonteCarloSimulationOutput|null;}
export interface UploadedDocumentChunk {id:string;fileName:string;documentType:'OFFTAKER_CONTRACT'|'AUDIT_REPORT'|'CREDIT_POLICY'|'SLIK_REPORT';pageNumber:number;content:string;tags:string[];}
export interface CreditWorkspaceState {version:'5.1.0';lastSaved:string|null;source:string;borrower:BorrowerProfile;groupExposure:GroupObligorProfile;bankReconciliation:BankReconciliationModule;financialSpreading:{years:FinancialStatementYear[]};existingDebts:ExistingDebtFacility[];equipmentDeal:EquipmentDealInputs;collateralModel:CollateralValuationModel;legalDiligence:{items:LegalDiligenceItem[]};offtakerContract:OfftakerContractProtection;qualitativeScorecard:QualitativeScorecardInputs;scenarios:Record<ScenarioType,ScenarioAdjustment>;monteCarlo:MonteCarloWorkspaceConfig;ragKnowledgeBase:UploadedDocumentChunk[];policy:{minimumDSCR:number;maximumLeverage:number;minimumBankRatio:number;maximumBankRatio:number;cashConversionThreshold:number};memo:{analyst:string;recommendation:string;rationale:string;conditions:string;exceptions:string;reviewDate:string};ui:{selectedScenario:ScenarioType;commonSize:boolean;compact:boolean};auditLog:{at:string;action:string}[];}
/** API credentials and chat history are session-only and are never members of CreditWorkspaceState. */
export interface CopilotRequestOptions {provider:'gemini'|'openai'|'claude';model:string;apiKey:string;query:string;snapshot:string;excerpts:UploadedDocumentChunk[];consent:boolean;signal?:AbortSignal;}
